import{c as a,Q as o,j as r,m as n}from"./chunks/framework.3U2mntTB.js";const p=JSON.parse('{"title":"Scenarios","description":"","frontmatter":{},"headers":[],"relativePath":"features/scenarios.md","filePath":"features/scenarios.md"}'),s={name:"features/scenarios.md"};function t(i,e,l,d,c,h){return o(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="scenarios" tabindex="-1">Scenarios <a class="header-anchor" href="#scenarios" aria-label="Permalink to &quot;Scenarios&quot;">​</a></h1><p>AetherUHC comes with <strong>139+ fully implemented, highly configurable scenarios</strong> out of the box. Scenarios modify the base rules of Ultra Hardcore to create unique, varied, and exciting gameplay experiences.</p><h2 id="enabling-disabling-scenarios" tabindex="-1">Enabling &amp; Disabling Scenarios <a class="header-anchor" href="#enabling-disabling-scenarios" aria-label="Permalink to &quot;Enabling &amp; Disabling Scenarios&quot;">​</a></h2><p>Scenarios can be toggled via the in-game GUI or commands:</p><ul><li><strong>Command:</strong> <code>/scenarios</code> (Opens the Scenario Manager menu)</li><li><strong>Host Permission required:</strong> <code>aetheruhc.host</code></li></ul><h2 id="popular-scenarios-included" tabindex="-1">Popular Scenarios Included <a class="header-anchor" href="#popular-scenarios-included" aria-label="Permalink to &quot;Popular Scenarios Included&quot;">​</a></h2><p>Here are just a few of the most popular scenarios included in AetherUHC:</p><h3 id="cutclean" tabindex="-1">CutClean <a class="header-anchor" href="#cutclean" aria-label="Permalink to &quot;CutClean&quot;">​</a></h3><p>Ores drop their smelted counterparts (e.g., Iron Ore drops Iron Ingots). Food drops cooked (e.g., Cows drop Steak). This eliminates the need for furnaces and speeds up the early game.</p><h3 id="timebomb" tabindex="-1">Timebomb <a class="header-anchor" href="#timebomb" aria-label="Permalink to &quot;Timebomb&quot;">​</a></h3><p>When a player dies, their items are placed in a chest rather than dropping on the ground. A countdown timer begins above the chest, and after 30 seconds, the chest explodes, destroying the loot and damaging anyone nearby.</p><h3 id="timber" tabindex="-1">Timber <a class="header-anchor" href="#timber" aria-label="Permalink to &quot;Timber&quot;">​</a></h3><p>Breaking the bottom block of a tree will cause the entire tree to break, dropping all logs and apples instantly.</p><h3 id="double-ores" tabindex="-1">Double Ores <a class="header-anchor" href="#double-ores" aria-label="Permalink to &quot;Double Ores&quot;">​</a></h3><p>All ores mined will drop double the normal yield.</p><h3 id="fireless" tabindex="-1">Fireless <a class="header-anchor" href="#fireless" aria-label="Permalink to &quot;Fireless&quot;">​</a></h3><p>Players cannot take fire or lava damage. This applies in both the Overworld and the Nether.</p><h3 id="bowless" tabindex="-1">Bowless <a class="header-anchor" href="#bowless" aria-label="Permalink to &quot;Bowless&quot;">​</a></h3><p>Bows cannot be crafted or used. String and Feathers cannot be obtained.</p><hr><blockquote><p><em>The full list of 139+ scenarios can be explored in-game via the <code>/scenarios</code> menu.</em></p></blockquote>',21)])])}const b=a(s,[["render",t]]);export{p as __pageData,b as default};
